      aspecto: "PARANOIA",
      custo: "1 PD",
      alc: "Curto",
      target: "1 Ser",
      duracao: "Instantâneo",
      resistencia: "Vontade parcial",
      desc: "Você sussurra boatos e mentiras que sua mente inventou, falsas verdades que apenas o alvo ouvem em sua mente, atingindo o como um martelo em sua nuca. O alvo sofre 3d6+2 pontos de dano mental e fica frustrado por uma rodada. Se passar no teste de resistênc metade do dano e evita a condição. O alvo precisa ter um cérebro ou ser capaz de pensar. Melhorado (+2 PD) - Muda o alcance para longo, o dano para 4d6+3 e o alvo para \"até 5 seres a sua escolha\". Genuíno (+5 PD) - Muda o alcance para extremo, o dano para 8d6+8 e a condição para esmorecido. Se passar no teste de resistência, em vez de esmorecido, fica frustrado.",
