      target: "Você",
      duracao: "Cena",
      resistencia: "-",
      desc: "Você modifica sua aparência de modo a parecer outra pessoa. Isso inclui altura, peso, tom de pele, cor de cabelo, timbre de voz, impressão digital, córnea etc. Você recebe - 2 em testes de perícias sociais para disfarce, mas não recebe habilidades da nova f estatísticas. Melhorado (+2 PV) - Muda o alcance para “curto” e o alvo para “1 ser”. Um alvo involuntária pode anular o efeito com um teste de Vontade. Genuíno (+5 PV) - Como em Melhorado, mas muda o alvo para “seres escolhidos”.",
