      desc: "Você faz uma sugestão a um alvo que deve ser capaz de ouvir (mas não precisa entender). Se falhar na resistência, ele deve obedecer a sugestão em seu próprio turno da melhor maneira possível. Escolha um dos efeitos. Fuja: O alvo gasta seu turno tentando se afastar de você (usando todas as suas ações). Largue: O alvo solta quaisquer itens que esteja segurando e não pode pegá los de volta até o início de seu próximo turno. Como esta é uma ação livre, ele ainda pode executar outras ações (exceto pegar aquilo que largou). Pare: O alvo fica pasmo (não pode realizar ações, só reações). Sente - se: Com uma ação livre, o alvo se senta no chão (se estava pendurado ou voando, desce até o chão). Ele pode fazer outras ações, mas não se levantar até o início de seu próximo turno. Venha: O alvo gasta seu turno se aproximando de você (usando todas as suas ações). Dance: O alvo dança, ficando com a condição trémulo. Melhorado (+2 PD) - Adiciona o seguinte comando: “: O alvo é acometido de dor aguda enquanto todo seu senso do que é real quebra. Ele sofre 3d8 pontos de dano paranormal e fica abalado por uma rodada”. Genuíno (+5 PD) - Escolha entre mudar o alvo para “Até 5 seres” ou adicionar o seguinte comando: “: O alvo deve fazer a ação agredir contra um outro alvo a sua escolha em alcance médio, com todas as suas capacidades”.",
