      duracao: "Cena",
      resistencia: "Vontade Anula",
      desc: "Você manda uma piscadela pro alvo, e de forma completamente incomum seu coração é tomado por um estranho sentimento de amor. O alvo deve fazer um teste de vontade e dependendo do resultado é tomado por um dos efeito: • Se passar: Nenhum efeito. • Se falhar por 5 ou menos personagem recebe +1d8 de vida temporária e fica com a condição Apaixonado. • Falhou por mais de 5: O personagem recebe +2d8 de vida temporários e fica com a condição Apaixonado. O efeito do ritual dura até o fim da cena ou até os pontos de vida temporário se forem. Se os PV acabarem durante a cena, o personagem não fica mais apaixonado porém recebe a condição Trêmulo. Se uma pessoa passar no teste do ritual ou tiver o efeito nulificado, o mesmo se torna imune a esses efeitos até o dia seguinte. “Apaixonado: O personagem passa a sentir paixão por alguém. Ele sofre penalidade igual aos PV recebidos durante o ritual em todos os testes contra a pessoa pela qual estiver apaixonado.” “Trêmulo. O personagem fica nervoso, tomado por tremeliques. Ele sofre +2 em testes de perícias físicas por 3 rodadas.” Melhorado (+3 PD) - Muda a resistência para Vontade Parcial, aumenta a vida temporária em ambos os casos em +1d8 e a primeira condição se torna \" Se passar: Fica com a condição Trémulo.\" Genuíno (+7 PD) - Como Melhorado, mas a vida temporária passa a ser d12 ao invés de d8 e pode escolher causar dano ao invés de dar vida temporária, tendo os mesmos efeitos da vida temporária porém com as condições invertidas (só sai de Apaixonado no final da cena ou após ser curado do dano)",
