      desc: "Você gera uma lufada sobrenatural constante. Escolha um dos efeitos a seguir. Puxar: Você pode usar uma ação de movimento para puxar um objeto de até 4 kg dentro do alcance. Se o objeto estiver livre, voa para suas mãos (caso tenha mãos livres para apanhá lo) ou para seus pés. Empurrar: Você repele objetos de até 5 kg (o que envolve quase todos os projéteis e armas de arremesso), recebendo resistência a balístico, cortante, impacto e perfurante 5. Melhorado (+2 PD) - Nesta versão a energia do vento é expelida de uma única vez e arremessa até 10 objetos, ou um total de 20 kg, o que for menor. Os objetos devem estar a até 3m uns dos outros. Objetos arremessados podem atingir seres em seu caminho, causando de 1 ponto de dano de impacto por quilo (objetos macios, sem pontas ou sem fio) até 1d6 pontos de dano por quilo (objetos duros, pontudos ou afiados). Seres atingidos têm direito a um teste de Reflexos para reduzir o dano à metade. Seres dentro da capacidade d arremessados, mas têm direito a um teste de Fortitude para evitar o efeito (em si mesmos ou em objetos que estejam segurando). Um ser arremessado contra uma superfície sólida sofre 1d6 pontos de dano de impacto para cada 3m que “voou” no deslocamento (incluindo outros seres; nesse caso, ambos sofrem o dano). Genuíno (+5 PD) - Muda o alcance para médio. Você pode usar uma ação de movimento para fazer com que a força da lufada levite e mova um ser ou objeto de até 140 kg por até 9m em qualquer direção dentro do alcance. Um ser pode anular o efeito sobre ele, ou sobre u m objeto que possua, passando num teste de Fortitude. O alvo cai no chão se sair do alcance ou o efeito terminar.",
