      desc: "O ritual transforma o corpo e equipamento dos alvos em energia pura e os faz reaparecer num lugar a sua escolha a até 1.000km. Quando conjura este ritual, você precisa fazer um teste de Usar o Véu, com DT definida pelo seu conhecimento sobre o destino. DT 3. Um lugar que você visita com frequência. DT 4. Um lugar que você já visitou pelo menos uma vez. DT 5. Um lugar que você nunca visitou e só conhece a partir da descrição de outra pessoa que esteve lá. Você não pode se teletransportar para um lugar que nunca visitou sem a descrição de alguém. Ou seja, não pode se transportar para “o local onde Júlia está presa” se nunca esteve lá nem falou com alguém que esteve. Se passar no teste, os alvos chegam ao lug em um lugar parecido, mas errado ou distante (até 1d10 x 10 km). Se você tiver uma falha crítica, o ritual falha, mas você leva o dano normalmente e fica atordoado por 1d4 rodadas. Genuíno (+5 PV) - pode se teletransportar para qualquer local na Terra.",
