      resistencia: "Fortitude reduz à metade (Morte)",
      desc: "ou Vontade anula (Evolução) Uma frequência impossível e harmônica ecoa do vazio, manifestando se como ondas entrópicas que se recusam a silenciar. O conjurador escolhe entre: • A Melodia da Morte: A vibração desintegra a matéria. Causa 9d6 pontos de dano paranormal e deixa os alvos Surdos por 1d4 rodadas. Fortitude reduz à metade e anula a surdez. Inimigos que sobreviverem continuam ouvindo um zumbido agudo que lhes dá +1 em Testes de Resistência a té o fim da cena. • O Hino da Evolução: Uma canção sublime que invade a mente dos aliados escolhidos. Eles não sofrem dano, mas a música passa a tocar em suas cabeças em \"loop\". O alvo tem que fazer um teste de Vontade ou levam 2 d4 de dano mental. Enquanto a música tocar, eles recebem - 3 em todos os testes e tornam - se imunes a efeitos de Medo ou Sono, pois a melodia ocupa todo o espaço em suas mentes. Melhorado (+4 PD): A nota final ressoa com o fervor da extinção. Na Melodia, o dano aumenta em +3d8. No Hino, o dano levado em caso de falha aumenta em +2d4 e os aliados também recebem uma ação de movimento adicional por turno, movendo - se no ritmo frenético da canção. Genuíno (+14 PD): Como Melhorado mas: A área aumenta para uma esfera de 18m de raio. A música torna - se tão absoluta que além de causar ambos os efeitos em simultâneo, qualquer ser que morrer na área (aliado ou inimigo) sob o efeito da canção se desfaz em uma canção pura de erradicação, c adjacentes e curando o conjurador ou qualquer pessoa escolhida pelo conjurador que ouça o Hino em 10 PV. Dizem que ninguém que ouve a melodia desconhecida esquece de seu som.",
