      desc: "Você aponta seus dedo na direção de um ser e pequenos fios como teias de aranha se amarram ao redor do alvo. O alvo deve fazer um teste de vontade (DT - Custo do Ritual), se falhar fica com a condição \"Praguejado\" até o fim da cena. Quando a cena acabar, se o alvo morreu seu corpo se decompõe rapidamente enquanto as pestes em seu corpo se alimentam do que sobrou. Praguejado: Enquanto o ser estiver vivo esse efeito não faz nada. Se um portador dessa condição morrer, seu corpo volta a vida com metade dos PV's máximos porém sendo controlado por quem conjurou o ritual. Esse corpo conta como uma criatura e todas os rolamentos de d ados feitos por ela são feitos com metade dos dados, incluindo rolamentos de dano. A criatura age no turno que ela agiria normalmente na iniciativa, porém quem define suas ações é o conjurador do ritual. Genuíno (+9 PV): Quando utiliza o ritual a duração da infecção para semana.",
