      resistencia: "Vontade Anula",
      desc: "Amaldiçoado Você convoca a energia primordial da realidade e corrige os erros cometidos pelo véu. Você escolhe um ser que tenha a condição Machucado e tenta banir o mesmo de volta de onde veio. O alvo deve fazer um teste de Vontade ou é apagado da existência. Se o rit paranormal ele apenas volta a ser um item normal. Esse ritual não funciona em pessoas com menos de 30 de GC ou com mais de 0 de humanidade.",
